<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/session.php';require_once __DIR__.'/../includes/functions.php';require_once __DIR__.'/../includes/admin_layout.php';if(!is_admin_logged_in())redirect('../index.php');
function fms_total($conn,$sql,$params=[]){$r=$params?pg_query_params($conn,$sql,$params):pg_query($conn,$sql);return $r?(int)pg_fetch_result($r,0,0):0;}
$totalCampaigns=fms_total($conn,'SELECT COUNT(*) FROM feedback_campaigns');$activeCampaigns=fms_total($conn,"SELECT COUNT(*) FROM feedback_campaigns WHERE status='active'");$closedCampaigns=fms_total($conn,"SELECT COUNT(*) FROM feedback_campaigns WHERE status='closed'");$totalParticipants=fms_total($conn,'SELECT COUNT(*) FROM feedback_participants');$responded=fms_total($conn,"SELECT COUNT(*) FROM feedback_participants WHERE status='responded'");$pending=fms_total($conn,"SELECT COUNT(*) FROM feedback_participants WHERE status='active'");$responseRate=$totalParticipants?round($responded/$totalParticipants*100,2):0;$totalQuestions=fms_total($conn,'SELECT COUNT(*) FROM feedback_questions');$writtenAnswers=fms_total($conn,"SELECT COUNT(*) FROM feedback_answers WHERE NULLIF(trim(text_value),'') IS NOT NULL");
$activeResult=pg_query($conn,"SELECT c.*,COUNT(DISTINCT q.id) question_count,COUNT(DISTINCT p.id) participant_count,COUNT(DISTINCT s.id) response_count FROM feedback_campaigns c LEFT JOIN feedback_questions q ON q.campaign_id=c.id LEFT JOIN feedback_participants p ON p.campaign_id=c.id LEFT JOIN feedback_submissions s ON s.campaign_id=c.id WHERE c.status='active' GROUP BY c.id ORDER BY c.start_at NULLS FIRST,c.id LIMIT 1");$activeCampaign=$activeResult&&pg_num_rows($activeResult)?pg_fetch_assoc($activeResult):null;
$upcomingResult=pg_query($conn,"SELECT * FROM feedback_campaigns WHERE status='draft' AND start_at>NOW() ORDER BY start_at LIMIT 1");$upcoming=$upcomingResult&&pg_num_rows($upcomingResult)?pg_fetch_assoc($upcomingResult):null;
$recent=pg_query($conn,"SELECT c.*,COUNT(DISTINCT q.id) question_count,COUNT(DISTINCT p.id) participant_count,COUNT(DISTINCT s.id) response_count FROM feedback_campaigns c LEFT JOIN feedback_questions q ON q.campaign_id=c.id LEFT JOIN feedback_participants p ON p.campaign_id=c.id LEFT JOIN feedback_submissions s ON s.campaign_id=c.id GROUP BY c.id ORDER BY c.created_at DESC LIMIT 5");
$activity=pg_query($conn,"SELECT s.reference_code,s.submitted_at,c.title FROM feedback_submissions s JOIN feedback_campaigns c ON c.id=s.campaign_id ORDER BY s.submitted_at DESC LIMIT 10");
admin_page_start('Dashboard','dashboard');?>
<div class="welcome-banner"><div><h2><i class="fas fa-hand-sparkles"></i> Welcome back, <?=h($_SESSION['admin_full_name']??'Administrator')?>!</h2><p><?=date('l, F j, Y')?> &nbsp;·&nbsp; Feedback Management System Admin Panel</p></div><div class="banner-icon"><i class="fas fa-shield-halved"></i></div></div>
<?php if($activeCampaign):?><div class="status-alert ongoing"><i class="fas fa-circle"></i><div><strong>Feedback Campaign In Progress:</strong> <?=h($activeCampaign['title'])?><?php if($activeCampaign['start_at']):?> &nbsp;·&nbsp; Started: <?=h(date('M d, Y h:i A',strtotime($activeCampaign['start_at'])))?><?php endif;?></div></div><?php elseif($upcoming):?><div class="status-alert upcoming"><i class="fas fa-clock"></i><div><strong>Upcoming Feedback Campaign:</strong> <?=h($upcoming['title'])?> &nbsp;·&nbsp; Starts: <?=h(date('M d, Y h:i A',strtotime($upcoming['start_at'])))?></div></div><?php else:?><div class="status-alert info"><i class="fas fa-info-circle"></i><div><strong>No active campaigns.</strong> Create a new feedback campaign to get started.</div></div><?php endif;?>
<div class="stats-grid"><div class="stat-card elections"><div class="stat-icon"><i class="fas fa-bullhorn"></i></div><div><div class="stat-number"><?=$totalCampaigns?></div><div class="stat-label">Total Campaigns</div><div class="stat-sub"><?=$activeCampaigns?> active · <?=$closedCampaigns?> closed</div></div></div><div class="stat-card voters"><div class="stat-icon"><i class="fas fa-user-check"></i></div><div><div class="stat-number"><?=$totalParticipants?></div><div class="stat-label">Registered Participants</div><div class="stat-sub"><?=$pending?> eligible to respond</div></div></div><div class="stat-card votes"><div class="stat-icon"><i class="fas fa-comment-dots"></i></div><div><div class="stat-number"><?=$responded?></div><div class="stat-label">Responses Submitted</div><div class="stat-sub"><?=$pending?> remaining</div></div></div><div class="stat-card turnout"><div class="stat-icon"><i class="fas fa-percentage"></i></div><div><div class="stat-number"><?=$responseRate?>%</div><div class="stat-label">Response Rate</div><div class="stat-sub"><?=$responded?> of <?=$totalParticipants?> participants</div></div></div><div class="stat-card positions"><div class="stat-icon"><i class="fas fa-circle-question"></i></div><div><div class="stat-number"><?=$totalQuestions?></div><div class="stat-label">Questions</div><div class="stat-sub">Across all campaigns</div></div></div><div class="stat-card candidates"><div class="stat-icon"><i class="fas fa-pen-to-square"></i></div><div><div class="stat-number"><?=$writtenAnswers?></div><div class="stat-label">Written Answers</div><div class="stat-sub">Open feedback received</div></div></div></div>
<div class="quick-actions"><h3><i class="fas fa-bolt"></i> Quick Actions</h3><div class="action-buttons"><a href="campaigns/index.php?action=new" class="action-btn primary"><i class="fas fa-plus-circle"></i> Create Campaign</a><a href="participants/generate.php" class="action-btn secondary"><i class="fas fa-user-plus"></i> Generate Participants</a><a href="questions/index.php" class="action-btn info"><i class="fas fa-circle-question"></i> Add Questions</a><a href="responses/index.php" class="action-btn success"><i class="fas fa-chart-pie"></i> View Responses</a><a href="results/live.php" class="action-btn primary"><i class="fas fa-chart-line"></i> Live Results</a></div></div>
<div class="dashboard-grid"><div class="panel"><div class="panel-header"><h3><i class="fas fa-history"></i> Recent Campaigns</h3><a href="campaigns/index.php">View All →</a></div><div class="panel-body"><?php if($recent&&pg_num_rows($recent)):while($c=pg_fetch_assoc($recent)):?><div class="election-item"><div class="election-info"><h4><?=h($c['title'])?></h4><p><?php if($c['start_at']):?><?=h(date('M d, Y',strtotime($c['start_at'])))?><?php else:?>No start date<?php endif;?> – <?php if($c['end_at']):?><?=h(date('M d, Y',strtotime($c['end_at'])))?><?php else:?>Open-ended<?php endif;?></p><div class="election-meta"><span><i class="fas fa-circle-question"></i> <?=(int)$c['question_count']?> questions</span><span><i class="fas fa-users"></i> <?=(int)$c['participant_count']?> participants</span><span><i class="fas fa-message"></i> <?=(int)$c['response_count']?> responses</span></div></div><span class="badge badge-<?=h($c['status'])?>"><?=h(ucfirst($c['status']))?></span></div><?php endwhile;else:?><div class="empty-state"><i class="fas fa-calendar-xmark"></i><p>No campaigns created yet.</p></div><?php endif;?></div><?php if($recent&&pg_num_rows($recent)):?><div class="panel-footer"><a href="campaigns/index.php">View All Campaigns <i class="fas fa-arrow-right"></i></a></div><?php endif;?></div>
<div class="panel"><div class="panel-header"><h3><i class="fas fa-clock-rotate-left"></i> Recent Activity</h3></div><div class="panel-body"><?php if($activity&&pg_num_rows($activity)):while($a=pg_fetch_assoc($activity)):?><div class="activity-item"><div class="activity-icon"><i class="fas fa-check"></i></div><div class="activity-info"><strong>Feedback submitted</strong><br><small><?=h($a['title'])?> · <?=h($a['reference_code'])?></small></div><div class="activity-time"><?=h(date('M d, h:i A',strtotime($a['submitted_at'])))?><br><small><?=h(timeAgo($a['submitted_at']))?></small></div></div><?php endwhile;else:?><div class="empty-state"><i class="fas fa-inbox"></i><p>No response activity yet.</p></div><?php endif;?></div></div></div>
<?php if($activeCampaign):?><div class="panel" style="margin-bottom:24px"><div class="panel-header"><h3><span class="status-dot ongoing"></span> Active Campaign Details</h3></div><div class="panel-body"><div class="ongoing-detail-grid"><div class="ongoing-detail-item"><div class="od-label">Campaign</div><div class="od-value"><?=h($activeCampaign['title'])?></div></div><div class="ongoing-detail-item"><div class="od-label">Start</div><div class="od-value"><?=$activeCampaign['start_at']?h(date('M d, Y h:i A',strtotime($activeCampaign['start_at']))):'Immediately'?></div></div><div class="ongoing-detail-item"><div class="od-label">End</div><div class="od-value"><?=$activeCampaign['end_at']?h(date('M d, Y h:i A',strtotime($activeCampaign['end_at']))):'Open-ended'?></div></div><div class="ongoing-detail-item"><div class="od-label">Questions</div><div class="od-value"><?=(int)$activeCampaign['question_count']?></div></div><div class="ongoing-detail-item"><div class="od-label">Participants</div><div class="od-value"><?=(int)$activeCampaign['participant_count']?></div></div><div class="ongoing-detail-item"><div class="od-label">Responses</div><div class="od-value"><?=(int)$activeCampaign['response_count']?></div></div></div></div></div><?php endif;?>
<?php admin_page_end();?>
